1	//! Shared helpers for the end-to-end regression tests: temporary files and
2	//! directories, LF joining of exact record sequences, and the strict
3	//! success-path assertion for `roottrace root`.
4	
5	// Not every helper is used by every integration-test target that includes
6	// this module (e.g. TempDir is only needed by root_regression).
7	#![allow(dead_code)]
8	
9	use std::fs;
10	use std::path::PathBuf;
11	use std::process::Command;
12	use std::sync::atomic::{AtomicU64, Ordering};
13	
14	static COUNTER: AtomicU64 = AtomicU64::new(0);
15	
16	pub fn bin() -> &'static str {
17	    env!("CARGO_BIN_EXE_roottrace")
18	}
19	
20	/// File that is deleted when the guard drops, even if the test panics.
21	pub struct TempFile {
22	    pub path: PathBuf,
23	}
24	
25	impl TempFile {
26	    pub fn create(data: &[u8]) -> Self {
27	        let id = COUNTER.fetch_add(1, Ordering::Relaxed);
28	        let path = std::env::temp_dir().join(format!(
29	            "roottrace-regtest-{}-{}",
30	            std::process::id(),
31	            id,
32	        ));
33	        fs::write(&path, data).unwrap_or_else(|e| panic!("cannot create {}: {e}", path.display()));
34	        TempFile { path }
35	    }
36	}
37	
38	impl Drop for TempFile {
39	    fn drop(&mut self) {
40	        let _ = fs::remove_file(&self.path);
41	    }
42	}
43	
44	/// Temporary directory (used to trigger "path is a directory" failures).
45	pub struct TempDir {
46	    pub path: PathBuf,
47	}
48	
49	impl TempDir {
50	    pub fn create() -> Self {
51	        let id = COUNTER.fetch_add(1, Ordering::Relaxed);
52	        let path = std::env::temp_dir()
53	            .join(format!("roottrace-regtest-dir-{}-{}", std::process::id(), id));
54	        fs::create_dir(&path).unwrap();
55	        TempDir { path }
56	    }
57	}
58	
59	impl Drop for TempDir {
60	    fn drop(&mut self) {
61	        let _ = fs::remove_dir(&self.path);
62	    }
63	}
64	
65	pub fn join_lf(records: &[&[u8]], trailing_lf: bool) -> Vec<u8> {
66	    let mut data: Vec<u8> = Vec::new();
67	    for (i, rec) in records.iter().enumerate() {
68	        if i > 0 {
