/// Independently verify an RFC 6962 inclusion proof: walk the path leaf to
/// root, tracking the covered [lo, hi) range so the combination direction
/// follows actual tree geometry rather than the proof producer's hints.
fn verify_proof(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
    assert!(m < n);
    let mut hash = leaf_hash(leaf);
    let (mut lo, mut hi) = (m, m + 1);
    for sibling in path {
        if lo % 2 == 1 || (lo == 0 && hi < n && hi.is_power_of_two()) {
            // Current subtree is a right child: sibling on the left.
            hash = node_hash(sibling, &hash);
            let width = hi - lo;
            lo -= width;
        } else {
            // Current subtree is a left child: sibling on the right.
            hash = node_hash(&hash, sibling);
            let width = hi - lo;
            hi += width;
        }
    }
    assert_eq!((lo, hi), (0, n), "proof must cover the whole batch");
    hash
}

